import {partyFX} from './party-fx.js';
import {FactoryGame} from './factory-engine.js';
import {loadWords} from './word-store.js';
import {readWords} from './vocab.js';
import {bindGameLifecycle} from './game-lifecycle.js';
const $=id=>document.getElementById(id);let game=null,paused=false,last=0,selected=null,wave=0,finished=false,drag=null,messageUntil=0;const nodes=new Map();
function note(text){$('status').textContent=text;messageUntil=performance.now()+1800;}
function release(){drag?.ghost?.remove();drag=null;}
function start(){partyFX.clear();const p=readWords(loadWords());try{if(p.errors.length)throw Error(p.errors[0]);game=new FactoryGame(p.entries);}catch(e){$('error').textContent=e.message;return;}release();for(const n of nodes.values())n.remove();nodes.clear();selected=null;paused=false;wave=0;finished=false;for(const id of['intro','result','pauseScreen'])$(id).classList.add('hidden');note('荷物を選んで、正しい宛先へ！');render();}
function deliver(bin){if(!game||paused||selected===null)return;const item=game.items.find(i=>i.id===selected),ok=game.drop(selected,bin);if(ok===null)return;if(ok){partyFX.burst('good',game.combo>1?game.combo+' COMBO!':'配達成功！',$('bins').children[bin]);note('配達成功！ '+game.combo+'連続！');selected=null;}else {partyFX.burst('miss','宛先をチェック！');note('正しい宛先は「'+game.bins[item.bin].meaning+'」');}release();render();}
function makeParcel(item){const el=document.createElement('button');el.className='parcel';el.type='button';el.textContent=item.word;el.classList.toggle('long',item.word.length>13);el.setAttribute('aria-label',item.word+'の荷物を選ぶ');el.onclick=()=>{if(!paused&&game.mode==='play'&&game.items.some(i=>i.id===item.id)){selected=item.id;render();}};el.addEventListener('pointerdown',e=>{if(paused||game.mode!=='play'||drag)return;e.preventDefault();selected=item.id;try{el.setPointerCapture(e.pointerId);}catch{}drag={pointer:e.pointerId,id:item.id,x:e.clientX,y:e.clientY,ghost:null};render();});el.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;if(!drag.ghost&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>8){drag.ghost=el.cloneNode(true);drag.ghost.classList.add('drag-ghost');drag.ghost.removeAttribute('aria-label');drag.ghost.setAttribute('aria-hidden','true');document.body.append(drag.ghost);}if(drag.ghost){drag.ghost.style.left=e.clientX-58+'px';drag.ghost.style.top=e.clientY-32+'px';}});el.addEventListener('pointerup',e=>{if(!drag||drag.pointer!==e.pointerId)return;const moved=!!drag.ghost;release();if(moved){const bin=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-bin]');if(bin)deliver(Number(bin.dataset.bin));}});for(const name of['pointercancel','lostpointercapture'])el.addEventListener(name,release);el.addEventListener('contextmenu',e=>e.preventDefault());return el;}
function render(){if(!game)return;const g=game;if(wave!==g.wave){wave=g.wave;selected=null;release();$('bins').replaceChildren();g.bins.forEach((p,i)=>{const b=document.createElement('button');b.className='bin';b.dataset.bin=i;b.textContent=p.meaning;b.onclick=()=>deliver(i);$('bins').append(b);});note('第'+wave+'便！ 宛先を確認しよう');}
 const live=new Set(g.items.map(i=>i.id));for(const[id,n]of nodes)if(!live.has(id)){n.remove();nodes.delete(id);if(selected===id)selected=null;if(drag?.id===id)release();}const width=Math.max(1,$('belt').clientWidth-122),height=$('belt').clientHeight/3;for(const item of g.items){let n=nodes.get(item.id);if(!n){n=makeParcel(item);nodes.set(item.id,n);$('belt').append(n);}n.style.left=width*item.age/12+'px';n.style.top=item.lane*height+8+'px';n.classList.toggle('chosen',selected===item.id);n.classList.toggle('blocked',item.lock>0);n.disabled=paused||item.lock>0||g.mode!=='play';}for(const b of $('bins').children)b.disabled=paused||selected===null||g.mode!=='play';$('time').textContent=Math.ceil(g.remaining)+'秒';$('lives').textContent='ミスあと'+g.lives+'回';$('count').textContent=g.sorted+' / 18個';$('score').textContent=g.score+'点 · 第'+g.wave+'便 / 3便';if(performance.now()>messageUntil)$('status').textContent=selected===null?'荷物を選んで、宛先をタップ':'この荷物の意味に合う宛先は？';if(g.mode!=='play'&&!finished){finished=true;release();partyFX.burst(g.mode==='won'?'win':'miss',g.mode==='won'?'DELIVERY CLEAR!':'お仕事終了！');$('resultTitle').textContent=g.mode==='won'?'配達クリア！':'お仕事終了！';$('resultScore').textContent=g.score+' pts';$('resultStats').textContent=g.sorted+' / 18個を配達';$('review').replaceChildren();for(const p of g.missed.values()){const row=document.createElement('p');row.textContent=p.word+' ＝ '+p.meaning;$('review').append(row);}$('result').classList.remove('hidden');}}
function pause(v){if(!game||game.mode!=='play')return;paused=v;if(v)partyFX.clear();release();$('pauseScreen').classList.toggle('hidden',!v);render();}
$('start').onclick=start;$('again').onclick=start;$('pause').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);bindGameLifecycle(window,document,{clearInput:release,pause});window.addEventListener('keydown',e=>{if(e.key==='Escape')pause(!paused);});function frame(t){const dt=last?Math.min(.1,(t-last)/1000):0;last=t;if(game&&!paused&&!document.hidden&&game.mode==='play'){game.tick(dt);render();}requestAnimationFrame(frame);}requestAnimationFrame(frame);
